namespace zdb {
CWorld::CWorld(const char* name)
	{
		/* 0x230030: a world is a grid node (type 6: CNode::UpdateGrid puts the children of
		   a type-6 parent into the grid - without it no cell or node ever reached the grid,
		   so nothing could be drawn or stood on), the current world, with a 256-hit DI ray,
		   one default sun (normalised (0.5, -0.8, 0.5), colour 0.8, ambient 0.2), the lens
		   colours and the shadow direction. The binary holds the CGrid by value (+0x670). */
		m_camera = NULL;
		m_diInt = NULL;
		m_Wind.Reset();
		m_cellData = NULL;
		m_maxOverlap = 2;

		m_grid = new CGrid();

		SetName(name);

		m_scale = 10.0f;
		m_invscale = 0.1f;
		m_world = this;
		m_type = 6;

		m_diInt = new DiIntersect(256);
		m_diIntDelayCnt = 0;

		sceVu0FVECTOR sun = { 0.5f, -0.8f, 0.5f, 1.0f };
		sceVu0Normalize(sun, sun);
		m_gLight.dir[0].x = sun[0];
		m_gLight.dir[0].y = sun[1];
		m_gLight.dir[0].z = sun[2];
		m_gLight.dir[0].w = sun[3];
		m_gLightDirUpdate = true;
		m_gLight.dir[1].x = 0.0f;
		m_gLight.dir[1].y = 0.0f;
		m_gLight.dir[1].z = 0.0f;
		m_gLight.dir[1].w = 0.0f;
		m_gLightDirUpdate = true;
		m_gLight.dir[2].x = 0.0f;
		m_gLight.dir[2].y = 0.0f;
		m_gLight.dir[2].z = 0.0f;
		m_gLight.dir[2].w = 0.0f;
		m_gLightDirUpdate = true;

		m_gLight.col[0].x = 0.8f;
		m_gLight.col[0].y = 0.8f;
		m_gLight.col[0].z = 0.8f;
		m_gLight.col[0].w = 1.0f;
		m_gLightColUpdate = true;
		m_gLight.col[1].x = 0.0f;
		m_gLight.col[1].y = 0.0f;
		m_gLight.col[1].z = 0.0f;
		m_gLight.col[1].w = 1.0f;
		m_gLightColUpdate = true;
		m_gLight.col[2].x = 0.0f;
		m_gLight.col[2].y = 0.0f;
		m_gLight.col[2].z = 0.0f;
		m_gLight.col[2].w = 1.0f;
		m_gLightColUpdate = true;
		m_gLight.ambient.x = 0.2f;
		m_gLight.ambient.y = 0.2f;
		m_gLight.ambient.z = 0.2f;
		m_gLight.ambient.w = 1.0f;
		m_gLightColUpdate = true;

		m_night_mission = false;
		m_lensfx_nvg.x = 0.2f;
		m_lensfx_nvg.y = 0.9f;
		m_lensfx_nvg.z = 0.2f;
		m_lensfx_starlightscope.x = 0.3f;
		m_lensfx_starlightscope.y = 0.5f;
		m_lensfx_starlightscope.z = 0.95f;

		/* port: not written - the four 256x256 shadow textures "ShadowX_%d" (new CTexture,
		   CTexture::LoadGS at zVid+0x48 | 0x80000000, 0x2303c8-0x230448); the shadow maps
		   (CRenderMap) are unwritten and LoadGS 0x2f9510 is a stub */
		for (s32 i = 0; i < 4; i++)
			m_shadowTex[i] = NULL;

		m_shadowTexH = NULL;
		m_shadow_vector.x = 1.0f;
		m_shadow_vector.y = -1.0f;
		m_shadow_vector.z = 1.0f;
		m_shadow_vector.Normalize();

		m_default_soiltype = 0;
		m_default_soiltype_name = NULL;
	}
}

/* @socom-skeleton stub __dt__Q23zdb6CWorldFv */
zdb::CWorld::~CWorld()
{
	/* 0x22fca0: the children (virtual DeleteChildren: CWorld's), the landmarks, the
	   camera, the DI ray, the shadow textures, every asset library (the recycle bin, then
	   the loaded list), the character and decal texture sets (their GS buffers go), the
	   node universe and the soil-type name; the members follow (the grid, the band
	   objects, the render and light maps, the lights). */
	CBeachBall::Uninit();
	DeleteChildren();

	for (CNodeVector::iterator it = m_landmarks.begin(); it != m_landmarks.end(); ++it)
		CNode::Delete(*it);

	m_landmarks.clear();

	if (m_camera != NULL)
		delete m_camera;

	m_camera = NULL;
	delete m_diInt;
	m_diInt = NULL;

	/* port: guard - the port's constructor does not create the shadow textures or their
	   handle (see the constructor); the ELF calls SetTexture/Destroy on the handle as is */
	if (m_shadowTexH != NULL)
	{
		m_shadowTexH->SetTexture(NULL);
		CTexHandle::Destroy(m_shadowTexH);
	}

	for (s32 i = 0; i < 4; i++)
		delete m_shadowTex[i];

	EmptyAssetRecycleBin();
	CAssetMgr::m_assets.Clear();
	m_TextureCharacterCommon.clear();
	m_TextureDecals.clear();

	while (m_TextureAssetCharacters.size() != 0)
	{
		CTextureAssetCharacters* set = const_cast<CTextureAssetCharacters*>(
			static_cast<const CTextureAssetCharacters*>(m_TextureAssetCharacters.front()));
		m_TextureAssetCharacters.erase(m_TextureAssetCharacters.begin());

		if (set != NULL)
		{
			CTexManager::m_texmanager.doDelBuffer(set->m_texBuffer);
			delete set;
		}
	}

	if (NodeUniverse != NULL)
	{
		NodeUniverse->clear();
		delete NodeUniverse;
		NodeUniverse = NULL;
	}

	m_world = NULL;

	if (m_default_soiltype_name != NULL)
		_free(m_default_soiltype_name, "node_world.cpp", 0x141);

	m_default_soiltype_name = NULL;

	/* port: the ELF destroys the CGrid it holds by value (+0x670) here, after the
	   texture lists; the port holds it through a pointer made in the constructor */
	delete m_grid;
	m_grid = NULL;
}

