namespace zdb {
void CWorld::GarbageCollect()
	{
		for (auto i = m_child.begin(); i != m_child.end(); ++i)
		{
			zdb::CNode* node = dynamic_cast<CCell*>(*i);

			if (!node)
				(*i)->ShrinkAtomBasePtrs();
		}
	}
}

