namespace zdb {
void CWorld::ReserveChildren(s32 count)
	{
		m_child.reserve(count + m_child.size()); /* 0x22f920: size (+0x6c), not capacity */
	}
}

/* @socom-skeleton body AddChild__Q23zdb6CWorldFPQ23zdb5CNode */
namespace zdb {
void CWorld::AddChild(CNode* child)
	{
		/* 0x22f6f0: leave the old parent, enter the grid, append to the children; a
		   type-2 node that casts a shadow or reflects gets a render map; a character-common
		   node goes dynamic, is marked a character and joins the common character texture
		   set. Was: no grid insert (cells never reached the grid), inserted at the front. */
		CNode* parent = child->m_parent;

		if (parent == this)
			return;

		if (parent != NULL && parent != this)
			parent->DeleteChild(child);

		m_grid->Insert(child);
		child->m_parent = this;

		if (m_child.size() == m_child.capacity())
			m_child.reserve(m_child.size() + 100);

		m_child.push_back(child);

		CNode* mapped = child->m_type == 2 ? child : NULL;

		if (mapped != NULL)
		{
			/* port: not written - the render maps (0x22f7c8-0x22f894): m_shadow -> new
			   CRenderMap(node, shadow, m_shadowTex[m_shadows.size()]), m_reflective -> a
			   reflection map, each appended to m_shadows. CRenderMap's constructor is a
			   stub and the shadow textures are not created. */
		}

		if (child->m_char_common)
		{
			child->SetDynamic(true, true);
			child->m_character = true;
			m_world->AddTextureAssetCharacter(CAssetMgr::m_assets.FindLib(CHARSETCOMMON), child);
		}
	}
}

/* @socom-skeleton stub DeleteChild__Q23zdb6CWorldFPQ23zdb5CNode */
short zdb::CWorld::DeleteChild(zdb::CNode *node)
{
	/* 0x22f530: a shadow caster's render maps go (delshadow deletes each map of the node),
	   a reflective node's maps too; then a child of the world leaves the grid (cells stay),
	   the children and its parent, and returns its remaining count (Release); a node that
	   is not a child returns its count unchanged */
	if (node == NULL)
		return 0;

	if (node->m_shadow)
	{
		struct delshadow
		{
			CNode* m_node;
			bool operator()(CRenderMap* map) const
			{
				if (map->m_node != m_node)
					return false;

				delete map;
				return true;
			}
		} pred = { node };

		m_shadows.erase(std::remove_if(m_shadows.begin(), m_shadows.end(), pred), m_shadows.end());
	}

	if (node->m_reflective)
	{
		for (CRenderMapVector::iterator it = m_shadows.begin(); it != m_shadows.end(); ++it)
		{
			if ((*it)->m_node == node)
			{
				/* ELF quirk: erases from the match to the end (not one element), deletes the
				   match it still holds, then keeps walking past the new end. port: stops
				   after the erase instead of running off the vector. */
				CRenderMap* map = *it;
				m_shadows.erase(it, m_shadows.end());
				delete map;
				break;
			}
		}
	}

	if (node->m_parent != this)
		return node->m_count;

	if (dynamic_cast<CCell*>(node) == NULL)
		m_grid->Remove(node);

	m_child.Remove(node);
	node->m_parent = NULL;
	return node->Release();
}

/* @socom-skeleton stub DeleteChildren__Q23zdb6CWorldFv */
void zdb::CWorld::DeleteChildren()
{
	/* 0x22f370: two passes over the children: first every node that is not a cell leaves
	   the grid and its last reference deletes it, then the cells are deleted; the list is
	   emptied without releasing its storage */
	CWorld* world = this;

	for (CNodeVector::iterator it = m_child.begin(); it != m_child.end(); ++it)
	{
		CNode* node = *it;

		if (dynamic_cast<CCell*>(node) == NULL)
		{
			world->m_grid->Remove(node);
			node->m_parent = NULL;

			if (node->Release() == 0 && node != NULL)
				delete node;

			node = NULL;
		}

		*it = node;
	}

	for (CNodeVector::iterator it = m_child.begin(); it != m_child.end(); ++it)
	{
		CNode* node = *it;
		CCell* cell = dynamic_cast<CCell*>(node);

		if (cell != NULL)
		{
			cell->m_parent = NULL;
			delete cell;
			node = NULL;
		}

		*it = node;
	}

	m_child.clear();
}

/* @socom-skeleton body Update__Q23zdb6CWorldFv */
void zdb::CWorld::Update()
{
	/* 0x22f2e0: tick the wind by the frame time, then, when changed, put the global light
	   directions and colours into the camera's VU1 frame packet (VU 16-19 normals,
	   20-23 colours: what the microcode lights dynamic objects such as characters with) */
	m_Wind.Tick(zVid.frameTime);
	tag_FrameSetup* vu = m_camera->m_mtxSet.m_vu;

	if (m_gLightDirUpdate)
	{
		sceVu0NormalLightMatrix(vu->mtxLightNormal, (f32*)&m_gLight.dir[0], (f32*)&m_gLight.dir[1], (f32*)&m_gLight.dir[2]);
		vu->mtxLightNormal[3][3] = 1.0f;
		m_gLightDirUpdate = false;
	}

	if (m_gLightColUpdate)
	{
		sceVu0LightColorMatrix(vu->mtxLightColor, (f32*)&m_gLight.col[0], (f32*)&m_gLight.col[1], (f32*)&m_gLight.col[2],
			(f32*)&m_gLight.ambient);
		m_gLightColUpdate = false;
	}
}

