/* @socom-skeleton stub GetIntersect__Q23zdb6CWorldFPC6CPnt3DPC6CPnt3D */
zdb::IntersectStruct * zdb::CWorld::GetIntersect(const CPnt3D *tail, const CPnt3D *tip)
{
	/* 0x22eb70: the world's DI ray tail -> tip through the grid; the hit nearest the
	   tail (NULL if none) */
	m_diInt->m_Tail = *tail;
	m_diInt->m_Tip = *tip;
	m_grid->GetIntersect(m_diInt);

	if (m_diInt->m_Cnt == 0)
		return NULL;

	return m_diInt->GetNearestIntersect();
}

/* @socom-skeleton stub GetIntersects__Q23zdb6CWorldFPC6CPnt3DPC6CPnt3D */
zdb::DiIntersect * zdb::CWorld::GetIntersects(const CPnt3D *tail, const CPnt3D *tip)
{
	/* 0x22eb00: as GetIntersect; every hit stays in m_diInt */
	m_diInt->m_Tail = *tail;
	m_diInt->m_Tip = *tip;
	m_grid->GetIntersect(m_diInt);
	return m_diInt;
}

/* @socom-skeleton stub GetAltitude__Q23zdb6CWorldFPC6CPnt3Df */
zdb::IntersectStruct * zdb::CWorld::GetAltitude(const CPnt3D *pos, float height)
{
	/* 0x22ea80: a vertical probe through pos's x/z with the world's DI ray; the highest
	   hit no more than `height` above pos (NULL if none) */
	m_diInt->m_Tail.x = pos->x;
	m_diInt->m_Tail.y = 0.0f;
	m_diInt->m_Tail.z = pos->z;
	m_grid->GetAltitude(m_diInt);

	if (m_diInt->m_Cnt == 0)
		return NULL;

	return m_diInt->GetHighestAltitude(pos, height);
}

/* @socom-skeleton stub GetAltitudes__Q23zdb6CWorldFPC6CPnt3Df */
zdb::DiIntersect * zdb::CWorld::GetAltitudes(const CPnt3D *pos, float)
{
	/* 0x22ea30: the world's altitude ray at pos's x/z through the grid (the height argument
	 * is not used); the hits stay in m_diInt */
	f32 z = pos->z;
	m_diInt->m_Tail.x = pos->x;
	m_diInt->m_Tail.y = 0.0f;
	m_diInt->m_Tail.z = z;
	m_grid->GetAltitude(m_diInt);
	return m_diInt;
}

