/* @socom-skeleton stub diTick__Q23zdb6CWorldFfPv */
bool zdb::CWorld::diTick(float, void *)
{
	/* 0x22e9c0 (task diTick 5.0, CMission::Open): run the intersections queued this frame
	   as one grid batch */
	m_world->m_grid->GetIntersectBatch(m_world->m_diIntDelay, m_world->m_diIntDelayCnt);
	m_world->m_diIntDelayCnt = 0;
	return false;
}

/* @socom-skeleton stub RegIntersectDelayed__Q23zdb6CWorldFPQ23zdb11DiIntersectPC6CPnt3DPC6CPnt3D */
int zdb::CWorld::RegIntersectDelayed(zdb::DiIntersect *di, const CPnt3D *tail, const CPnt3D *tip)
{
	/* 0x22e940: queue a chord (type 2) for this frame's diTick batch (up to 256); -1
	   without a DI or with the queue full, else its queue slot */
	if (di == NULL)
		return -1;

	s32 slot = m_diIntDelayCnt;

	if (slot >= 256)
		return -1;

	m_diIntDelayCnt = slot + 1;
	m_diIntDelay[slot] = di;
	di->m_Type = 2;
	di->m_Tail = *tail;
	di->m_Tip = *tip;
	return slot;
}

/* @socom-skeleton stub RegIgnoreNodeDelayed__Q23zdb6CWorldFPQ23zdb11DiIntersectPQ23zdb5CNode */
void zdb::CWorld::RegIgnoreNodeDelayed(zdb::DiIntersect *di, zdb::CNode *node)
{
	/* 0x22e910: the node (and its tree) the delayed DI skips. port: the ELF returns -1
	   without a DI or node, else 1; the port declaration is void */
	if (di == NULL || node == NULL)
		return;

	di->m_Node = node;
}

/* @socom-skeleton stub ClearIgnoreNodeDelayed__Q23zdb6CWorldFPQ23zdb11DiIntersect */
void zdb::CWorld::ClearIgnoreNodeDelayed(zdb::DiIntersect *di)
{
	/* 0x22e8f0. port: the ELF returns -1 without a DI, else 1; the port declaration is void */
	if (di == NULL)
		return;

	di->m_Node = NULL;
}

/* @socom-skeleton stub RegProximityDelayed__Q23zdb6CWorldFPQ23zdb11DiIntersectPC6CPnt3Df */
int zdb::CWorld::RegProximityDelayed(zdb::DiIntersect *di, const CPnt3D *pos, float radius)
{
	/* 0x22e880: queue a proximity sphere (type 4: centre in m_Tail, radius in m_Tip.x)
	   as RegIntersectDelayed */
	if (di == NULL)
		return -1;

	s32 slot = m_diIntDelayCnt;

	if (slot >= 256)
		return -1;

	m_diIntDelayCnt = slot + 1;
	m_diIntDelay[slot] = di;
	di->m_Type = 4;
	di->m_Tail = *pos;
	di->m_Tip.x = radius;
	di->m_Tip.y = 0.0f;
	di->m_Tip.z = 0.0f;
	return slot;
}

/* @socom-skeleton stub Segregate_CCells__Q23zdb6CWorldFPQ23zdb5CNodeRQ23zdb11CNodeVectorRQ23zdb11CNodeVector */
void zdb::CWorld::Segregate_CCells(zdb::CNode *node, zdb::CNodeVector &cells, zdb::CNodeVector &others)
{
	/* 0x22e760: split the node's children into grid cells and the rest (the ELF also
	   casts the node to CWorld and ignores the result) */
	if (node == NULL)
		return;

	for (CNodeVector::iterator it = node->m_child.begin(); it != node->m_child.end(); ++it)
	{
		CCell* cell = dynamic_cast<CCell*>(*it);

		if (cell != NULL)
			cells.insert(cells.end(), 1, cell);
		else
			others.insert(others.end(), 1, *it);
	}
}

/* @socom-skeleton body DismemberWorldModel__Q23zdb6CWorldFv */
namespace zdb {
bool CWorld::DismemberWorldModel()
	{
		/* 0x22e640 (LoadWorld): the "worldmodel" model's children become world children,
		   appended, each entering the grid (was: front insert, no grid update - the
		   world geometry never reached the grid) */
		CModel* worldmodel = CAssetMgr::m_assets.GetModel("worldmodel");
#ifdef SOCOM_PORT
		{
			const unsigned* r = socom_port_node_reads;
			SOCOM_PORT_TRACE("WORLD: worldmodel %p (%d children); world has %d children; nodes read by type 0-9: %u %u %u %u %u %u %u %u %u %u, instances %u, version-0 %u",
				worldmodel, worldmodel != NULL ? (int)worldmodel->m_child.size() : -1, (int)m_child.size(),
				r[0], r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9], r[10], r[11]);
		}
#endif

		if (!worldmodel)
			return false;

		ReserveChildren(worldmodel->m_child.size());

		for (CNodeVector::iterator it = worldmodel->m_child.begin(); it != worldmodel->m_child.end(); ++it)
		{
			CNode* child = *it;
			m_child.push_back(child);
			child->m_parent = this;
			m_grid->Update(child);
		}

		worldmodel->m_child.clear();

		/* port: not done - the ELF then deletes the emptied model (virtual deleting
		   destructor, 0x22e720); ~CModel/~CNode are unwritten here and the model is still
		   listed in its asset library, so it is kept */
		return true;
	}
}

